from collections import deque
from copy import deepcopy
import weakref


_pending_sources = deque()
_pending_source_set = set()
_is_propagating = False


def _snapshot_value(value):
    """Keep a stable comparison value without requiring values to be copyable."""
    try:
        snapshot = deepcopy(value)
    except Exception:
        return value

    # Objects that use identity equality are not value-comparable after a
    # deepcopy.  Preserve the original object so an unchanged singleton does
    # not look like a change merely because it was copied.
    value_type = type(value)
    if (
        snapshot is not value
        and value_type.__eq__ is object.__eq__
        and value_type.__ne__ is object.__ne__
    ):
        return value

    return snapshot


class Cell:
    def __init__(self, initial_value):
        self._value = initial_value
        self._dependents = []

    def _add_dependent(self, dependent):
        self._dependents.append(weakref.ref(dependent))

    def _live_dependents(self):
        live_dependents = []
        live_references = []

        for dependent_reference in self._dependents:
            dependent = dependent_reference()
            if dependent is not None:
                live_dependents.append(dependent)
                live_references.append(dependent_reference)

        if len(live_references) != len(self._dependents):
            self._dependents = live_references

        return live_dependents

    @property
    def value(self):
        return self._value


class InputCell(Cell):
    def __init__(self, initial_value):
        # Store directly so construction cannot start propagation.
        super().__init__(initial_value)

    @Cell.value.setter
    def value(self, new_value):
        if new_value == self._value:
            return

        self._value = new_value
        _propagate(self)


class ComputeCell(Cell):
    def __init__(self, inputs, compute_function):
        self._inputs = list(inputs)
        self._compute = compute_function
        self._callbacks = []
        super().__init__(None)

        for input_cell in self._inputs:
            input_cell._add_dependent(self)

        self._recompute()
        self._stable_value = _snapshot_value(self._value)

    def _recompute(self):
        self._value = self._compute([input_cell.value for input_cell in self._inputs])

    def add_callback(self, callback):
        self._callbacks.append(callback)
        return callback

    def remove_callback(self, callback):
        for index, registered_callback in enumerate(self._callbacks):
            if registered_callback is callback:
                del self._callbacks[index]
                return

    def _fire_callbacks(self):
        for callback in list(self._callbacks):
            if any(registered_callback is callback for registered_callback in self._callbacks):
                callback(self._value)


def _propagate(source):
    """Recompute all compute-cell descendants of a changed input."""
    global _is_propagating

    if _is_propagating:
        if source not in _pending_source_set:
            _pending_source_set.add(source)
            _pending_sources.append(source)
        return

    _is_propagating = True
    if source not in _pending_source_set:
        _pending_source_set.add(source)
        _pending_sources.append(source)

    try:
        while _pending_sources:
            current_source = _pending_sources.popleft()
            _pending_source_set.remove(current_source)
            _propagate_once(current_source)
    except BaseException:
        _pending_sources.clear()
        _pending_source_set.clear()
        raise
    finally:
        _is_propagating = False


def _propagate_once(source):
    affected = []
    seen = set()
    pending = deque(source._live_dependents())

    while pending:
        cell = pending.popleft()
        if cell in seen:
            continue

        seen.add(cell)
        affected.append(cell)
        pending.extend(cell._live_dependents())

    if not affected:
        return

    indegree = {cell: 0 for cell in affected}

    for cell in affected:
        for input_cell in cell._inputs:
            if input_cell in seen:
                indegree[cell] += 1

    ready = deque(cell for cell in affected if indegree[cell] == 0)
    ordered = []

    while ready:
        cell = ready.popleft()
        ordered.append(cell)

        for dependent in cell._live_dependents():
            if dependent in seen:
                indegree[dependent] -= 1
                if indegree[dependent] == 0:
                    ready.append(dependent)

    previous_values = {cell: cell._stable_value for cell in ordered}

    for cell in ordered:
        cell._recompute()

    changed_cells = []
    for cell in ordered:
        if cell.value != previous_values[cell]:
            changed_cells.append(cell)
        cell._stable_value = _snapshot_value(cell.value)

    for cell in changed_cells:
        cell._fire_callbacks()
